import { faker } from "@faker-js/faker";
import { Avatar, Badge, Box, Stack, Typography } from "@mui/material";
import { useTheme, styled } from "@mui/material/styles";
import StyledBadge from './StyledBadge';
import { useDispatch, useSelector } from "react-redux";
import { SelectConversation } from "../redux/slices/app";
import { FetchCurrentMessages, SetConversationRead, SetCurrentConversation } from "../redux/slices/conversation";
import { useEffect, useState } from "react";
import { convertToDate, convertToIST } from "../utils/formatTime";

const truncateText = (string, n) => {
    return string?.length > n ? `${string?.slice(0, n)}...` : string;
};



const ChatElement = ({ id, name, img, online }) => {
    const user_id = window.localStorage.getItem("user_id");
    const theme = useTheme();
    const dispatch = useDispatch();
    const { messages } = useSelector((state) => state.conversation.direct_chat);
    const [lastMessage, setLastMessage] = useState(null);
    const [lastMessageTime, setLastMessageTime] = useState(null);
    const [unread, setUnread] = useState(0);

    useEffect(() => {
        const this_conversation = messages.find((el) => el.id === id);
        setLastMessage(this_conversation?.last_message);
        setLastMessageTime(convertToIST(this_conversation?.last_message_time));
        setUnread(this_conversation?.unread);
    }, [messages, unread]);

    return (
        <Box
            onClick={() => {
                dispatch(SelectConversation({ room_id: id }));
                dispatch(SetCurrentConversation({ room_id: id }));
                dispatch(SetConversationRead({ room_id: id, user_id: user_id }));
            }}
            sx={{
                borderRadius: 2,
                backgroundColor: theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper,
                boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)",
                cursor: 'pointer',
                transition: "0.1s ease-in-out", // Smooth transition effect
                '&:hover': {
                    backgroundColor: theme.palette.action.hover, // Change background color on hover
                    transform: 'scale(1.05);',
                },
            }}
            p={2}>
            <Stack
                direction='row'
                alignItems={'center'}
                justifyContent='space-between'
            >
                <Stack direction={'row'} spacing={2}>
                    {online ?
                        (
                            <StyledBadge overlap="circular" anchorOrigin={{ vertical: "bottom", horizontal: "right" }} variant="dot">
                                <Avatar src={img} />
                            </StyledBadge>
                        ) : (<Avatar src={img} />)
                    }

                    <Stack spacing={0.3}>
                        <Typography variant='subtitle2'>{truncateText(name, 15)}</Typography>
                        <Typography variant='caption'>{truncateText(lastMessage, 20)}</Typography>
                    </Stack>
                </Stack>
                <Stack spacing={2} alignItems={'center'}>
                    <Typography sx={{ fontWeight: 600 }} variant='caption'>
                        {lastMessageTime}
                    </Typography>
                    <Badge color='primary' badgeContent={unread}>
                    </Badge>
                </Stack>
            </Stack>
        </Box>
    )
};

export default ChatElement;